10	/**
11	 * Rejects a create request once its business day's registrations have reached capacity: the day is
12	 * full when {@link #DAILY_LIMIT} or more existing owners already carry the new owner's (adjusted)
13	 * registration date. Runs after {@link ResolveRegistrationDate}, so a weekend request counts against
14	 * the Monday it rolled to. A full day is a 429 via {@link DailyOwnerLimitException}.
15	 */
16	public class EnsureDailyOwnerLimit {
17	
18	    /** Maximum number of owners that may be registered on a single business day. */
19	    static final int DAILY_LIMIT = 100;
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DailyOwnerLimitException {
22	        LocalDate day = owner.getRegistrationDate();
23	        long registeredThatDay = ownerRepository.countRegisteredOn(day);
24	        if (registeredThatDay >= DAILY_LIMIT) {
25	            throw new DailyOwnerLimitException(DAILY_LIMIT);
26	        }
27	    }
28	}
