7	/**
8	 * Flags a create request as a bulk signup: the owner's bulk-signup warning is set when more than
9	 * {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered on its (business-day-adjusted)
10	 * registration date. Runs after {@link ResolveRegistrationDate} so it keys off the adjusted date,
11	 * and before {@link SaveOwner} so the count excludes the owner currently being created — the same
12	 * accumulation {@link EnsureDailyOwnerLimit} uses. Mutates the built {@link Owner} in place.
13	 */
14	public class FlagBulkSignup {
15	
16	    /** A day is a bulk-signup day once more than this many owners are already registered on it. */
17	    static final int BULK_SIGNUP_THRESHOLD = 80;
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        long alreadyRegistered = ownerRepository.countRegisteredOn(owner.getRegistrationDate());
21	        owner.setBulkSignupWarning(alreadyRegistered > BULK_SIGNUP_THRESHOLD);
22	    }
23	}
